const it = items[0];
const b = it.binary && it.binary.data;
const d = $('Entrada').first().json || {};
if (b) {
  b.fileName = String(d.nombreArchivoPropuesta || 'Propuesta').replace(/[^\w.\-]+/g, '_') + '.pdf';
  b.mimeType = 'application/pdf';
}
return items;

const d = $('Entrada').first().json || {};
const bin = items[0].binary && items[0].binary.data;
let base64 = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  base64 = buf.toString('base64');
} catch (e) {
  base64 = (bin && bin.data) || '';
}
if (!base64) throw new Error('No hay PDF de propuesta para adjuntar');

const PREGUNTAS = [["P1 · Etapa del negocio", "P1"], ["P2 · Sector principal", "P2"], ["P3 · Subsector", "P3"], ["P4 · Tamaño del equipo", "P4"], ["P5 · Volumen anual de ingresos", "P5"], ["P6 · Gestión Financiera", "P6"], ["P7 · Gestión Comercial", "P7"], ["P8 · Gestión de Procesos", "P8"], ["P9 · Gestión Tecnológica", "P9"], ["P10 · Gestión de Personas", "P10"], ["P11 · Principal drenaje de energía", "P11"], ["P12 · Problema #1 a resolver", "P12"]];
const r = d.respuestas || {};
const esc = (s) => String(s == null ? '—' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const filas = PREGUNTAS.map(([label, k]) => `
  <tr>
    <td style="padding:7px 10px;border-bottom:1px solid #DDE3EA;width:36%;color:#19325A;font-weight:600;">${esc(label)}</td>
    <td style="padding:7px 10px;border-bottom:1px solid #DDE3EA;">${esc(r[k])}</td>
  </tr>`).join('');

const nombreArchivo = String(d.nombreArchivoPropuesta || 'Propuesta').replace(/[^\w.\-]+/g, '_') + '.pdf';

const html = `
<div style="font-family:Helvetica,Arial,sans-serif;color:#172230;font-size:14px;line-height:1.6">
  <div style="background:#091B33;padding:18px 22px;margin-bottom:22px">
    <img src="https://www.grupoempodera.com/img/logo-horiz-white.png" alt="Grupo Empodera" style="height:30px;display:block">
  </div>
  <p style="margin:0 0 14px">Se completó un nuevo <strong>Diagnóstico Express</strong> y se generó la propuesta sugerida para el cliente.</p>
  <table style="width:100%;border-collapse:collapse;margin:0 0 20px;font-size:13px">
    <tr><td style="padding:6px 10px;border:1px solid #DDE3EA;background:#F5F6F8;width:26%"><b>Empresa</b></td><td style="padding:6px 10px;border:1px solid #DDE3EA">${esc(d.empresa)}</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #DDE3EA;background:#F5F6F8"><b>Contacto</b></td><td style="padding:6px 10px;border:1px solid #DDE3EA">${esc(d.nombre)}</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #DDE3EA;background:#F5F6F8"><b>Correo</b></td><td style="padding:6px 10px;border:1px solid #DDE3EA">${esc(d.correo)}</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #DDE3EA;background:#F5F6F8"><b>Teléfono</b></td><td style="padding:6px 10px;border:1px solid #DDE3EA">${esc(d.contacto)}</td></tr>
  </table>

  <h3 style="color:#091B33;font-size:15px;margin:0 0 8px;border-bottom:2px solid #EA560D;padding-bottom:6px">Preguntas y respuestas del diagnóstico</h3>
  <table style="width:100%;border-collapse:collapse;font-size:12px">${filas}</table>

  <p style="margin:22px 0 0;font-size:12px;color:#5C6B7E">El PDF con la propuesta completa va adjunto. El cliente recibió su versión sin la sección de propuesta.</p>
</div>`;

const text = `Nuevo Diagnóstico Express — ${d.empresa || 'sin empresa'}

Contacto: ${d.nombre || '—'}
Correo: ${d.correo || '—'}
Teléfono: ${d.contacto || '—'}

Preguntas y respuestas:
${PREGUNTAS.map(([label, k]) => `- ${label}: ${r[k] == null ? '—' : r[k]}`).join('\n')}

El PDF con la propuesta completa va adjunto.`;

return [{ json: {
  from: 'Diagnóstico Empodera <diagnostico@contact.grupoempodera.com>',
  to: ['fpaz@pe.grupoempodera.com', 'bnunez@co.grupoempodera.com', 'jcastillo@co.grupoempodera.com'],
  reply_to: d.correo || 'contacto@pe.grupoempodera.com',
  subject: `Diagnóstico + propuesta — ${d.empresa || 'sin empresa'}`,
  html,
  text,
  attachments: [{ filename: nombreArchivo, content: base64 }],
} }];

